import { useEffect, useState } from 'react'
import { Box, Button, Group, Loader, Modal, Text } from '@mantine/core'
import { ListDriveFolder } from '../../../wailsjs/go/main/App'
import { DriveAssignment } from './useDriveAssignments'

interface DriveFolder {
  id: string
  name: string
}

const ROOT: DriveFolder = { id: 'root', name: '/' }
const INDENT_PER_LEVEL = 16

interface DriveTreeNodeProps {
  item: DriveFolder
  path: string
  selectedId: string | null
  onSelect: (item: DriveFolder, path: string) => void
  defaultExpanded?: boolean
}

function DriveTreeNode({ item, path, selectedId, onSelect, defaultExpanded }: DriveTreeNodeProps) {
  const [expanded, setExpanded] = useState(defaultExpanded ?? false)
  const [children, setChildren] = useState<DriveFolder[] | null>(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const load = async () => {
    setLoading(true)
    setError(null)
    try {
      const items = await ListDriveFolder(item.id)
      setChildren(items.filter(i => i.isFolder).map(i => ({ id: i.id, name: i.name })))
    } catch (e) {
      setError(String(e))
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    if (defaultExpanded && children === null) load()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  const toggle = () => {
    if (!expanded && children === null) load()
    setExpanded(prev => !prev)
  }

  return (
    <Box>
      <Group gap={4} wrap="nowrap">
        <button
          type="button"
          onClick={toggle}
          aria-expanded={expanded}
          aria-label={expanded ? `Collapse ${item.name}` : `Expand ${item.name}`}
          style={{ width: 16, flexShrink: 0, border: 'none', background: 'transparent', padding: 0, cursor: 'pointer' }}
        >
          {loading ? <Loader size={10} /> : <Text size="xs" c="dimmed">{expanded ? '▼' : '▶'}</Text>}
        </button>
        <button
          type="button"
          onClick={() => onSelect(item, path)}
          style={{
            flex: 1,
            textAlign: 'left',
            border: 'none',
            padding: '2px 6px',
            borderRadius: 4,
            cursor: 'pointer',
            fontFamily: 'inherit',
            background: item.id === selectedId ? 'var(--mantine-color-blue-1)' : 'transparent',
          }}
        >
          <Text size="sm" fw={item.id === selectedId ? 600 : 400}>📁 {item.name}</Text>
        </button>
      </Group>
      {error && <Text size="xs" c="red" pl={INDENT_PER_LEVEL + 6}>{error}</Text>}
      {expanded && children && (
        <Box pl={INDENT_PER_LEVEL}>
          {children.length === 0
            ? <Text size="xs" c="dimmed" pl={6}>No subfolders</Text>
            : children.map(child => (
                <DriveTreeNode
                  key={child.id}
                  item={child}
                  path={path.endsWith('/') ? `${path}${child.name}` : `${path}/${child.name}`}
                  selectedId={selectedId}
                  onSelect={onSelect}
                />
              ))}
        </Box>
      )}
    </Box>
  )
}

interface Props {
  opened: boolean
  onClose: () => void
  onSelect: (folder: DriveAssignment) => void
}

export default function DriveFolderPickerModal({ opened, onClose, onSelect }: Props) {
  const [selected, setSelected] = useState<{ id: string; name: string; path: string } | null>(null)

  useEffect(() => {
    if (!opened) setSelected(null)
  }, [opened])

  const confirm = () => {
    if (!selected) return
    onSelect({ driveFolderId: selected.id, path: selected.path })
    onClose()
  }

  return (
    <Modal opened={opened} onClose={onClose} title="Choose a Drive folder" size="md">
      <Box style={{ maxHeight: 400, overflowY: 'auto' }}>
        <DriveTreeNode
          item={ROOT}
          path={ROOT.name}
          selectedId={selected?.id ?? null}
          onSelect={(item, path) => setSelected({ id: item.id, name: item.name, path })}
          defaultExpanded
        />
      </Box>
      <Group justify="flex-end" mt="md">
        <Button variant="default" onClick={onClose}>Cancel</Button>
        <Button disabled={!selected} onClick={confirm}>
          {selected ? `Select "${selected.name}"` : 'Select'}
        </Button>
      </Group>
    </Modal>
  )
}

import { useRef, useState, useEffect } from 'react'
import { useVirtualizer } from '@tanstack/react-virtual'
import { Box, Text } from '@mantine/core'
import * as pageCache from '../../lib/pageCache'
import { makeResizeDragHandler } from '../../lib/resizableWidth'
import { DEFAULT_WIDTH, DRAG_HANDLE_WIDTH, ITEM_PADDING, LABEL_HEIGHT, PAGE_ASPECT } from '../../constants'
import PageThumbnail from '../PageThumbnail'

const MIN_WIDTH = 120
const MAX_WIDTH = 480

interface Props {
  pdfPath: string | null
  pageCount: number
  selectedPage: number
  onSelectPage: (page: number) => void
}

// Read-only single-file thumbnail strip for the Drive Upload preview - unlike
// SplitMode/MergeMode's panels, there's no rotate/skip/reorder here since
// Drive Upload doesn't edit pages, just files to their destination.
export default function DriveThumbnailPanel({ pdfPath, pageCount, selectedPage, onSelectPage }: Props) {
  const [panelWidth, setPanelWidth] = useState(DEFAULT_WIDTH)
  const startDrag = makeResizeDragHandler(panelWidth, setPanelWidth, MIN_WIDTH, MAX_WIDTH)
  const thumbWidth = panelWidth - ITEM_PADDING * 2
  const thumbHeight = Math.round(thumbWidth * PAGE_ASPECT)
  const itemHeight = thumbHeight + LABEL_HEIGHT + ITEM_PADDING

  const scrollRef = useRef<HTMLDivElement>(null)
  pageCache.usePageCacheRender()

  const virtualizer = useVirtualizer({
    count: pageCount,
    getScrollElement: () => scrollRef.current,
    estimateSize: () => itemHeight,
    overscan: 3,
  })

  useEffect(() => {
    virtualizer.measure()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [itemHeight, pageCount])

  // Keyed on the visible range so this only re-runs when scroll position, data, or
  // sizing actually change - same technique as the other ThumbnailPanels.
  useEffect(() => {
    if (!pdfPath) return
    for (const item of virtualizer.getVirtualItems()) pageCache.load(pdfPath, item.index + 1, thumbWidth)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [virtualizer.range?.startIndex, virtualizer.range?.endIndex, pdfPath, thumbWidth])

  useEffect(() => {
    if (pageCount > 0) virtualizer.scrollToIndex(selectedPage - 1, { align: 'auto' })
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedPage])

  useEffect(() => {
    if (!pdfPath) return
    const handler = (e: KeyboardEvent) => {
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return
      if (e.key === 'ArrowLeft' && selectedPage > 1) { e.preventDefault(); onSelectPage(selectedPage - 1) }
      else if (e.key === 'ArrowRight' && selectedPage < pageCount) { e.preventDefault(); onSelectPage(selectedPage + 1) }
    }
    window.addEventListener('keydown', handler)
    return () => window.removeEventListener('keydown', handler)
  }, [pdfPath, selectedPage, pageCount, onSelectPage])

  return (
    <Box style={{ display: 'flex', height: '100%', flexShrink: 0 }}>
      <Box style={{ width: panelWidth, height: '100%', display: 'flex', flexDirection: 'column' }}>
        {!pdfPath ? (
          <Box
            style={{
              flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center',
              background: 'var(--mantine-color-gray-1)',
            }}
          >
            <Text size="sm" c="dimmed">Select a file to preview</Text>
          </Box>
        ) : (
          <div
            ref={scrollRef}
            style={{ flex: 1, minHeight: 0, overflowY: 'auto', overflowX: 'hidden', background: 'var(--mantine-color-gray-3)' }}
          >
            <div style={{ height: virtualizer.getTotalSize(), position: 'relative' }}>
              {virtualizer.getVirtualItems().map(item => {
                const page = item.index + 1
                return (
                  <div
                    key={item.key}
                    style={{ position: 'absolute', top: item.start, left: 0, width: '100%', height: item.size }}
                  >
                    <PageThumbnail
                      src={pageCache.getSrc(pdfPath, page)}
                      pdfPath={pdfPath}
                      page={page}
                      thumbHeight={thumbHeight}
                      isSelected={page === selectedPage}
                      isSkipped={false}
                      rotation={0}
                      isHovered={false}
                      label={String(page)}
                      onClick={() => onSelectPage(page)}
                      onRotate={() => {}}
                      onToggleSkip={() => {}}
                    />
                  </div>
                )
              })}
            </div>
          </div>
        )}
      </Box>

      <div
        onMouseDown={startDrag}
        style={{ width: DRAG_HANDLE_WIDTH, height: '100%', cursor: 'col-resize', flexShrink: 0, background: 'var(--mantine-color-gray-3)' }}
      />
    </Box>
  )
}
